/*
 * pp-cpp-crypto: compiler features for GCC and Clang builds, force-included
 * into every libsodium source. Upstream's configure detects these; the CMake
 * build does not, and without them the SIMD implementations compile empty and
 * the 64-bit field arithmetic falls back to 32-bit limbs.
 *
 * Every SIMD source sets its own target with a pragma and libsodium picks an
 * implementation by the CPU at run time, so the library still runs on CPUs
 * without these extensions. Keyed on the target architecture, not on CMake
 * checks, so multi-architecture builds get each slice right.
 * Generated by scripts/generate_libsodium_cmake.py.
 */
#ifndef PP_SODIUM_FEATURES_H
#define PP_SODIUM_FEATURES_H

#if defined(__SIZEOF_INT128__)
# define HAVE_TI_MODE 1
#endif

#if defined(__BYTE_ORDER__) && __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
# define NATIVE_LITTLE_ENDIAN 1
#endif

#if defined(__x86_64__) || defined(__i386__)
# define HAVE_CPUID 1
# define HAVE_MMINTRIN_H 1
# define HAVE_EMMINTRIN_H 1
# define HAVE_PMMINTRIN_H 1
# define HAVE_TMMINTRIN_H 1
# define HAVE_SMMINTRIN_H 1
# define HAVE_AVXINTRIN_H 1
# define HAVE_AVX2INTRIN_H 1
# define HAVE_AVX512FINTRIN_H 1
# define HAVE_WMMINTRIN_H 1
#endif

#endif
